"""SeongEraStudy Christmas landing page.

Install Flask, then run python app_updated.py. Production WSGI servers can
load app_updated:app. The configuration below can also be set through
environment variables.

The original videos are used by default. A background.mp4 or owner.mp4 next
to this file takes precedence, as does an explicit BACKGROUND_VIDEO_FILE
or OWNER_VIDEO_FILE. Set SITE_URL to the public HTTPS URL behind a proxy.
"""

import base64
import os
from pathlib import Path
from urllib.parse import urlsplit

from flask import Flask, Response, abort, render_template_string, request, send_file, url_for


def public_url(name, default=""):
    url = os.environ.get(name, default).strip()
    if url:
        parts = urlsplit(url)
        if parts.scheme not in {"http", "https"} or not parts.hostname:
            raise ValueError(f"{name} must be an HTTP or HTTPS URL")
    return url


PORTAL_LINK = public_url("PORTAL_LINK", "https://seongxcollege.duckdns.org")
CHANNEL_LINK = public_url("CHANNEL_LINK", "https://t.me/SeongEraStudy")
OWNER_LINK = public_url("OWNER_LINK", "https://t.me/SeongEra")
OWNER_NAME = os.environ.get("OWNER_NAME", "夔🌑 𝑺𝒆𝒐𝒏𝒈-𝒋𝒆 ⋆ 𝑂𝑓𝑓𝑙𝑖𝑛𝑒")

VIDEO_URL = public_url(
    "VIDEO_URL",
    "https://huggingface.co/datasets/gopallikehack/Seong_Study/resolve/main/n-261124-kcctgu.mp4",
)
OWNER_VIDEO_URL = public_url(
    "OWNER_VIDEO_URL",
    "https://huggingface.co/datasets/gopallikehack/Seong_Study/resolve/main/a-261025-y6jc8x.mp4",
)

SITE_URL = public_url("SITE_URL").rstrip("/")
VERSION = "christmas-portal-2026.1"
APP_DIRECTORY = Path(__file__).resolve().parent
VIDEO_FILES = {
    "background": Path(os.environ.get("BACKGROUND_VIDEO_FILE") or APP_DIRECTORY / "background.mp4").expanduser().resolve(),
    "owner": Path(os.environ.get("OWNER_VIDEO_FILE") or APP_DIRECTORY / "owner.mp4").expanduser().resolve(),
}
VIDEO_LINKS = {"background": VIDEO_URL, "owner": OWNER_VIDEO_URL}
LEGACY_NAMES = {"logo.png": "logo.png", "tree.webp": "tree.webp", "gifts.webp": "gifts.webp", "santa.webp": "sleigh.webp"}

app = Flask(__name__)


def video_source(name):
    if VIDEO_FILES[name].is_file():
        return url_for("serve_video", name=name)
    return VIDEO_LINKS[name]


@app.after_request
def security_headers(response):
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Content-Security-Policy"] = (
        "default-src 'self'; base-uri 'none'; frame-ancestors 'none'; "
        "form-action 'none'; object-src 'none'; media-src 'self' https: http:"
    )
    return response


@app.get("/")
def home():
    return render_template_string(
        HTML,
        base=SITE_URL or request.url_root.rstrip("/"),
        version=VERSION,
        icons=ICONS,
        portal=PORTAL_LINK,
        channel=CHANNEL_LINK,
        owner=OWNER_LINK,
        owner_name=OWNER_NAME,
        background_video=video_source("background"),
        owner_video=video_source("owner"),
    )


@app.get("/healthz")
def health():
    return {"status": "ok", "version": VERSION}


@app.get("/media/<name>.mp4")
def serve_video(name):
    path = VIDEO_FILES.get(name)
    if path is None or not path.is_file():
        abort(404)
    return send_file(path, mimetype="video/mp4", conditional=True, max_age=3600)


def asset_response(name):
    item = ASSETS.get(name)
    if item is None:
        abort(404)
    data, mimetype = item
    response = Response(data, mimetype=mimetype)
    response.cache_control.public = True
    response.cache_control.max_age = 86400
    response.add_etag()
    return response.make_conditional(request)


@app.get("/assets/<name>")
def asset(name):
    return asset_response(name)


@app.get("/a/<name>")
def legacy_asset(name):
    return asset_response(LEGACY_NAMES.get(name))


@app.get("/og.jpg")
def social_image():
    return asset_response("share.jpg")


@app.get("/favicon.ico")
def favicon():
    return asset_response("logo.png")


