SCRIPT = r"""
"use strict";

const byId = (id) => document.getElementById(id);
const motion = window.matchMedia("(prefers-reduced-motion: reduce)");
const stage = byId("welcome");
const toast = byId("toast");
let toastTimeout;

function announce(message) {
  window.clearTimeout(toastTimeout);
  toast.hidden = false;
  toast.textContent = message;
  toastTimeout = window.setTimeout(() => {
    toast.hidden = true;
    toast.textContent = "";
  }, 3200);
}

const countdowns = Array.from(document.querySelectorAll("[data-date]"), (element) => ({
  target: new Date(element.dataset.date + "T00:00:00").getTime(),
  message: element.dataset.greeting,
  counter: element.querySelector(".counter"),
  greeting: element.querySelector(".countdown-greeting"),
  parts: Object.fromEntries(Array.from(element.querySelectorAll("[data-part]"), (part) => [part.dataset.part, part])),
}));
let countdownInterval;

function renderCountdowns() {
  let hasFutureDate = false;
  const now = Date.now();
  for (const countdown of countdowns) {
    const total = Math.ceil((countdown.target - now) / 1000);
    if (total <= 0) {
      countdown.counter.hidden = true;
      countdown.greeting.hidden = false;
      countdown.greeting.textContent = countdown.message;
      continue;
    }
    hasFutureDate = true;
    const values = {
      days: Math.floor(total / 86400),
      hours: Math.floor((total % 86400) / 3600),
      minutes: Math.floor((total % 3600) / 60),
      seconds: total % 60,
    };
    for (const [part, value] of Object.entries(values)) {
      const text = String(value).padStart(2, "0");
      if (countdown.parts[part].textContent !== text) countdown.parts[part].textContent = text;
    }
    countdown.counter.hidden = false;
    countdown.greeting.hidden = true;
  }
  if (!hasFutureDate) window.clearInterval(countdownInterval);
  return hasFutureDate;
}

if (renderCountdowns()) countdownInterval = window.setInterval(renderCountdowns, 1000);

const background = byId("background-video");
const playback = byId("video-toggle");
const music = byId("music-toggle");
const snowToggle = byId("snow-toggle");
let stageVisible = true;
let playbackWanted = !motion.matches;
let audioWanted = false;
let backgroundFailed = false;

function paintMediaControls() {
  if (!background) return;
  const playing = !background.paused && !background.ended;
  const audible = !background.muted && audioWanted;
  playback.setAttribute("aria-label", playing ? "Pause background video" : "Play background video");
  playback.querySelector(".media-label").textContent = playing ? "Pause video" : "Play video";
  playback.querySelector(".media-icon-play").hidden = playing;
  playback.querySelector(".media-icon-pause").hidden = !playing;
  music.setAttribute("aria-pressed", String(audible));
  music.querySelector(".media-label").textContent = audible ? "Music on" : "Music off";
  music.querySelector(".media-icon-off").hidden = audible;
  music.querySelector(".media-icon-on").hidden = !audible;
}

function syncBackground() {
  if (!background || backgroundFailed) return;
  if (document.hidden || !stageVisible || !playbackWanted) {
    background.pause();
    paintMediaControls();
    return;
  }
  background.muted = !audioWanted;
  if (!background.getAttribute("src")) background.src = background.dataset.source;
  background.play().catch((error) => {
    if (error.name === "NotAllowedError") {
      playbackWanted = false;
      audioWanted = false;
      background.muted = true;
    }
    paintMediaControls();
  });
  paintMediaControls();
}

function muteBackground() {
  audioWanted = false;
  if (background) background.muted = true;
  paintMediaControls();
}

if (background) {
  background.addEventListener("loadedmetadata", () => {
    const aspect = background.videoWidth / background.videoHeight;
    stage.dataset.videoShape = aspect < 1.24 ? "portrait" : "landscape";
  });
  background.addEventListener("playing", () => {
    stage.dataset.videoReady = "true";
    paintMediaControls();
  });
  for (const event of ["play", "pause", "volumechange"]) {
    background.addEventListener(event, paintMediaControls);
  }
  background.addEventListener("error", () => {
    backgroundFailed = true;
    stage.removeAttribute("data-video-ready");
    playback.hidden = true;
    music.hidden = true;
    byId("background-error").hidden = false;
  });

  playback.addEventListener("click", () => {
    playbackWanted = background.paused;
    if (!playbackWanted) muteBackground();
    syncBackground();
  });
  music.addEventListener("click", () => {
    if (audioWanted) {
      muteBackground();
      return;
    }
    audioWanted = true;
    playbackWanted = true;
    syncBackground();
  });
}

const canvas = byId("snow");
const drawing = canvas.getContext("2d");
let snowAllowed = !motion.matches && !!drawing;
let snowFrame;
let snowWidth = 0;
let snowHeight = 0;
let flakes = [];
let previousFrame = 0;

function resizeSnow() {
  const ratio = Math.min(window.devicePixelRatio || 1, 1.5);
  snowWidth = stage.clientWidth;
  snowHeight = stage.clientHeight;
  canvas.width = Math.round(snowWidth * ratio);
  canvas.height = Math.round(snowHeight * ratio);
  drawing.setTransform(ratio, 0, 0, ratio, 0, 0);
  const count = Math.min(70, Math.max(18, Math.round(snowWidth * snowHeight / 19000)));
  flakes = Array.from({ length: count }, () => ({
    x: Math.random() * snowWidth,
    y: Math.random() * snowHeight,
    radius: 0.7 + Math.random() * 1.4,
    speed: 13 + Math.random() * 20,
    drift: 6 * (Math.random() - 0.5),
    opacity: 0.19 + Math.random() * 0.48,
  }));
}

function paintSnow(time) {
  const delta = previousFrame ? Math.min(0.05, (time - previousFrame) / 1000) : 0;
  previousFrame = time;
  drawing.clearRect(0, 0, snowWidth, snowHeight);
  drawing.fillStyle = "#fff8e1";
  for (const flake of flakes) {
    flake.x += flake.drift * delta;
    flake.y += flake.speed * delta;
    if (flake.y > snowHeight + 4) flake.y = -4;
    if (flake.x < -4) flake.x = snowWidth + 4;
    if (flake.x > snowWidth + 4) flake.x = -4;
    drawing.globalAlpha = flake.opacity;
    drawing.beginPath();
    drawing.arc(flake.x, flake.y, flake.radius, 0, Math.PI * 2);
    drawing.fill();
  }
  drawing.globalAlpha = 1;
  snowFrame = window.requestAnimationFrame(paintSnow);
}

function syncSnow() {
  if (!drawing) {
    snowToggle.hidden = true;
    return;
  }
  const active = snowAllowed && !motion.matches;
  snowToggle.setAttribute("aria-pressed", String(active));
  snowToggle.querySelector(".media-label").textContent = active ? "Snow on" : "Snow off";
  snowToggle.hidden = motion.matches;
  if (active && stageVisible && !document.hidden) {
    if (!snowFrame) {
      resizeSnow();
      snowFrame = window.requestAnimationFrame(paintSnow);
    }
  } else {
    window.cancelAnimationFrame(snowFrame);
    snowFrame = undefined;
    previousFrame = 0;
    drawing.clearRect(0, 0, snowWidth, snowHeight);
  }
}

snowToggle.addEventListener("click", () => {
  snowAllowed = !snowAllowed;
  syncSnow();
});
window.addEventListener("resize", () => {
  if (snowFrame) resizeSnow();
});
motion.addEventListener("change", () => {
  if (motion.matches) {
    playbackWanted = false;
    muteBackground();
  }
  syncBackground();
  syncSnow();
});

if ("IntersectionObserver" in window) {
  new IntersectionObserver(([entry]) => {
    stageVisible = entry.isIntersecting;
    syncBackground();
    syncSnow();
  }).observe(stage);
}
document.addEventListener("visibilitychange", () => {
  syncBackground();
  syncSnow();
});

const ownerLink = byId("owner-open");
const dialog = byId("owner-dialog");
const ownerVideo = byId("owner-video");
if (ownerLink && typeof dialog.showModal === "function") {
  ownerLink.addEventListener("click", (event) => {
    if (event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
    event.preventDefault();
    muteBackground();
    byId("owner-error").hidden = true;
    ownerVideo.src = ownerLink.href;
    dialog.showModal();
  });
  ownerVideo.addEventListener("error", () => {
    if (dialog.open) byId("owner-error").hidden = false;
  });
  byId("owner-close").addEventListener("click", () => dialog.close());
  dialog.addEventListener("click", (event) => {
    if (event.target === dialog) dialog.close();
  });
  dialog.addEventListener("close", () => {
    ownerVideo.pause();
    ownerVideo.removeAttribute("src");
    ownerVideo.load();
  });
}

const holidayCard = byId("holiday-card");
const celebrate = byId("celebrate");
celebrate.hidden = false;
celebrate.addEventListener("click", () => {
  announce("Merry Christmas and Happy New Year 2027!");
  if (motion.matches || holidayCard.classList.contains("celebrating")) return;
  holidayCard.classList.add("celebrating");
  window.setTimeout(() => holidayCard.classList.remove("celebrating"), 3650);
});

const share = byId("share");
if (navigator.share || navigator.clipboard?.writeText) {
  share.hidden = false;
  share.addEventListener("click", async () => {
    const url = document.querySelector('meta[property="og:url"]').content;
    try {
      if (navigator.share) {
        await navigator.share({ title: "SeongEraStudy · Christmas Edition", url });
      } else {
        await navigator.clipboard.writeText(url);
        announce("Link copied");
      }
    } catch (error) {
      if (error.name !== "AbortError") announce("Couldn’t share the page");
    }
  });
}

byId("media-tools").hidden = false;
syncBackground();
syncSnow();
"""


